```typescript
// R2 にアップロードされた画像に AI で説明をつけて D1 に保存する Agent
// 起動経路: R2 Event Notification → Queue → Worker → env.AGENT.create({ key })
export class CaptionAgent extends WorkflowEntrypoint<Env, { key: string }> {
  async run(event: WorkflowEvent<{ key: string }>, step: WorkflowStep) {
    const { key } = event.payload;

    const image = await step.do("fetch from R2", async () => {
      const obj = await this.env.BUCKET.get(key);
      return new Uint8Array(await obj!.arrayBuffer());
    });

    const caption = await step.do("caption", async () =>
      this.env.AI.run("@cf/llava-hf/llava-1.5-7b-hf",
        { image: [...image], prompt: "Describe this image in one sentence" },
        { gateway: { id: "caption-agent" } })
    );

    await step.do("save to D1", async () =>
      this.env.DB.prepare(
        "INSERT INTO captions (key, text, at) VALUES (?, ?, ?)"
      ).bind(key, caption.description, Date.now()).run()
    );
  }
}
```

