// 起動経路: R2 Event Notification → Queue → Worker → env.AGENT.create({ key })
export class ImageAgent extends WorkflowEntrypoint<Env, { key: string }> {
  async run(event: WorkflowEvent<{ key: string }>, step: WorkflowStep) {
    const { key } = event.payload;

    const image = await step.do("fetch from R2", async () => {
      const obj = await this.env.BUCKET.get(key);
      return new Uint8Array(await obj!.arrayBuffer());
    });

    const desc = await step.do("describe", async () =>
      this.env.AI.run("@cf/llava-hf/llava-1.5-7b-hf",
        { image: [...image], prompt: "Describe this image in detail" },
        { gateway: { id: "image-agent" } })
    );

    const emb = await step.do("embed", async () =>
      this.env.AI.run("@cf/baai/bge-base-en-v1.5",
        { text: desc.description })
    );

    await step.do("upsert to Vectorize", async () =>
      this.env.VECTORIZE.upsert([{
        id: key,
        values: emb.data[0],
        metadata: { key, description: desc.description },
      }])
    );
  }
}
```

